"use strict";(self.webpackChunkappbaza=self.webpackChunkappbaza||[]).push([[1477],{10:e=>{e.exports=JSON.parse('{"blogPosts":[{"id":"welcome-appbaza","metadata":{"permalink":"/blog/welcome-appbaza","source":"@site/blog/2023-06-04-welcome-appbaza/index.md","title":"Welcome AppBaza","description":"AppBaza is a one-person tech company focusing on open-source and open-core projects.","date":"2023-06-04T00:00:00.000Z","formattedDate":"June 4, 2023","tags":[{"label":"AppBaza","permalink":"/blog/tags/app-baza"},{"label":"open-source","permalink":"/blog/tags/open-source"},{"label":"open core","permalink":"/blog/tags/open-core"}],"readingTime":1.4,"hasTruncateMarker":false,"authors":[{"name":"Kanan Rahimov","title":"AppBaza","url":"https://github.com/KenanBek","imageURL":"https://github.com/KenanBek.png","key":"KenanBek"}],"frontMatter":{"slug":"welcome-appbaza","title":"Welcome AppBaza","authors":["KenanBek"],"tags":["AppBaza","open-source","open core"],"hide_table_of_contents":false}},"content":"[AppBaza](https://appbaza.com) is a one-person tech company focusing on open-source and open-core projects.\\n\\n## Projects\\n\\nMost of my projects come out of my needs from different personal initiatives.\\n\\nCurrently, I am focusing on the following areas:\\n\\n* Ready-to-use project templates with already integrated management dashboards and 3rd party integrations. An example is\\n  the Next.js project with an already integrated Stripe and an admin management dashboard where you can see and manage\\n  subscriptions. Follow the [NEST](/nest) project for more information.\\n* Tooling for monitoring your products and tracking certain events like registration, sale, and errors. With a mobile\\n  client and an API to integrate. Follow the [MOBYD](/mobyd) project for more information.\\n* Set of ready-to-use AI API integrations with some advanced features on top of it. I will share more details soon.\\n\\n:::tip Let\'s connect\\n\\nIf you want to join early access or chat, poke me on [my Twitter](https://twitter.com/KenanBekk).\\n\\n:::\\n\\n## Process\\n\\nMy work process is as follows:\\n\\n1. Prepare high-level design and initial specification (API specification, for example). Add to documentation.\\n2. Define integration points and write them down. Usually, this also ends up in the documentation.\\n3. Start the work piece by piece, and iterate.\\n\\nMost of the time, documentation for the project is available even before the project is published. But this might change\\nafter a couple of major iterations.\\n\\n## What\'s next?\\n\\nThe primary goal, for now, is to get mentioned projects ready for early access and, in parallel, extend their\\ndocumentation.\\n\\nFrom time to time, I will write a blog post to bring clarity to the progress.\\n\\nStay in touch!\\n\\nKen ( mail me at `ken + @ + this domain` )\\n\\n*Last updated: June 8, 2023*"}]}')}}]);